-- Module library: full-text search with PostgreSQL alone (ADR 0002). Each passage and each document
-- carries two vectors, generated by PostgreSQL from what they index: they cannot drift from it, and
-- no path that writes a text, a title or a language can forget them.

-- The words of a document in its language ("serveurs" finds "serveur"), accents and capitals
-- ignored. The stop words written with accents ("à", "été", "même") are recognized first, with the
-- list shipped with PostgreSQL: once unaccent has removed their accents, the stemmer would keep them.
create text search dictionary lore_french_stop (template = pg_catalog.simple, stopwords = french, accept = false);

create text search configuration lore_fr (copy = pg_catalog.french);
create text search configuration lore_en (copy = pg_catalog.english);
create text search configuration lore_simple (copy = pg_catalog.simple);

-- unaccent, in the schema its extension was created in (some hosts keep extensions apart).
do $$
declare
    accents text := (select quote_ident(n.nspname) || '.unaccent' from pg_extension e
                     join pg_namespace n on n.oid = e.extnamespace where e.extname = 'unaccent');
begin
    execute 'alter text search configuration lore_fr alter mapping for asciiword, word, hword, hword_part,'
        || ' asciihword, hword_asciipart with lore_french_stop, ' || accents || ', pg_catalog.french_stem';
    execute 'alter text search configuration lore_en alter mapping for asciiword, word, hword, hword_part,'
        || ' asciihword, hword_asciipart with ' || accents || ', pg_catalog.english_stem';
    execute 'alter text search configuration lore_simple alter mapping for asciiword, word, hword, hword_part,'
        || ' asciihword, hword_asciipart with ' || accents || ', pg_catalog.simple';
end
$$;

-- lore_simple: the words as written, without accents or capitals: pg_restore, app_rw or
-- ERR_CONN_RESET are found as they are pasted. In the three configurations, numbers, addresses,
-- versions, paths and web addresses keep the dictionaries of the copied ones, which keep them whole.

-- The bodies below are SQL-standard: PostgreSQL resolves the configurations when they are created,
-- and pg_dump writes them with their schema, so that pg_restore computes the vectors again whatever
-- its search path.
create function lore_config(language text) returns regconfig
    language sql immutable parallel safe
    return case language when 'fr' then 'lore_fr'::regconfig when 'en' then 'lore_en'::regconfig
           else 'lore_simple'::regconfig end;

-- array_to_string is not immutable, for every type; for an array of text it is.
create function lore_join(parts text[]) returns text
    language sql immutable parallel safe
    return array_to_string(parts, ' ');

-- A passage: the titles of its sections (weight B), then its text (weight D).
create function lore_passage_vector(config regconfig, headings text[], content text) returns tsvector
    language sql immutable parallel safe
    return setweight(to_tsvector(config, lore_join(headings)), 'B') || setweight(to_tsvector(config, content), 'D');

-- A document: its title (weight A), then its description (weight B).
create function lore_document_vector(config regconfig, title text, description text) returns tsvector
    language sql immutable parallel safe
    return setweight(to_tsvector(config, title), 'A') || setweight(to_tsvector(config, coalesce(description, '')), 'B');

-- The language chosen by a person is kept when the same version is extracted again.
alter table document_version add column language_chosen boolean not null default false;

-- The language of the version, copied where the generated vectors read it.
alter table chunk add column language text not null default 'other' check (language in ('fr', 'en', 'other'));
-- Null while the current version has no language yet: its title is then indexed as written.
alter table document add column search_language text check (search_language in ('fr', 'en', 'other'));

update chunk c set language = v.language
from document_version v
where v.id = c.version_id and v.language in ('fr', 'en');

update document d set search_language = v.language
from document_version v
where v.id = d.current_version_id and v.language is not null;

-- The text and the vectors of a passage are kept apart from its row: the rows stay small, and the
-- indexes lead to the documents that hold a word without reading every vector (measured on 300,000
-- passages: a frequent word in 70 ms instead of 13 s). Set before the columns are added, so that
-- the rewrite below applies it.
alter table chunk set (toast_tuple_target = 128);

-- PostgreSQL computes the vectors of every passage already imported: no extraction again.
alter table chunk
    add column tsv_lang tsvector generated always as (lore_passage_vector(lore_config(language), headings, content)) stored,
    add column tsv_simple tsvector generated always as (lore_passage_vector('lore_simple'::regconfig, headings, content)) stored;

alter table document
    add column tsv_lang tsvector generated always as (lore_document_vector(lore_config(search_language), title, description)) stored,
    add column tsv_simple tsvector generated always as (lore_document_vector('lore_simple'::regconfig, title, description)) stored;

create index chunk_tsv_lang_idx on chunk using gin (tsv_lang);
create index chunk_tsv_simple_idx on chunk using gin (tsv_simple);
create index document_tsv_lang_idx on document using gin (tsv_lang);
create index document_tsv_simple_idx on document using gin (tsv_simple);

-- The statistics of the rewritten tables, for the plans of the first searches.
analyze chunk;
analyze document;
